    val rows: List<GoldenRow> by lazy {
        TABLE.lines().filter { it.isNotBlank() }.map(GoldenRow::fromLine)
    }

    fun hashFor(fixture: String, vendorKeyPresent: Boolean, profile: String): String? =
        rows.firstOrNull { it.fixture == fixture && it.vendorKeyPresent == vendorKeyPresent && it.profile == profile }?.planHash
